"use strict";

const { Readable, Transform, Writable } = require("stream");
const { pipeline } = require("stream/promises");

module.exports = async function runPipelineProbe(parts) {
  const chunks = [];
  const upper = new Transform({
    transform(chunk, encoding, callback) {
      callback(null, String(chunk).toUpperCase());
    },
  });
  const joiner = new Transform({
    transform(chunk, encoding, callback) {
      callback(null, chunks.length === 0 ? chunk : Buffer.concat([Buffer.from("-"), Buffer.from(chunk)]));
    },
  });
  const sink = new Writable({
    write(chunk, encoding, callback) {
      chunks.push(Buffer.from(chunk));
      callback();
    },
  });

  await pipeline(Readable.from(parts), upper, joiner, sink);
  const text = Buffer.concat(chunks).toString("utf8");
  return { text, bytes: Buffer.byteLength(text) };
};
